struct T{int x,y;};struct I{int x,y;char t;};
int main(){int _px=40,_py=12,_wood=6,_hung=100,_thi=100,_t=0;std::vector<T>_raft={{38,12},{39,12},{40,12},{41,12},{42,12}};std::vector<I>_its;for(int i=0;i<8;i++)_its.push_back({rand()%80,rand()%25,(char)(rand()%2?'W':'P')});int _sx=10,_sy=5,_cd=0;std::cout<<"RAFT 2.0 WASD move B build(4w) Q quit\n";while(true){if(_kbhit()){char k=_getch();if(k=='q')break;if(k=='w')_py--;if(k=='s')_py++;if(k=='a')_px--;if(k=='d')_px++;if(_px<0)_px=0;if(_px>79)_px=79;if(_py<0)_py=0;if(_py>24)_py=24;if(k=='b'&&_wood>=4){_wood-=4;_raft.push_back({_raft.back().x+1,_raft.back().y});}for(int i=_its.size()-1;i>=0;i--){if(_its[i].x==_px&&_its[i].y==_py){if(_its[i].t=='W')_wood++;_its.erase(_its.begin()+i);}}} _t++;_thi-=(_t%20==0);_hung-=(_t%40==0);int dx=_px-_sx,dy=_py-_sy;if(dx)_sx+=dx/abs(dx?dx:1)*(rand()%2);if(dy)_sy+=dy/abs(dy?dy:1)*(rand()%2);if(--_cd<0&&abs(dx)+abs(dy)<4&&_raft.size()>1){_raft.pop_back();_cd=50;std::cout<<"SHARK BIT YOUR RAFT!\n";Sleep(500);}if(_hung<=0||_thi<=0){std::cout<<"YOU DIED - RAFT 2.0\n";break;}if(_t%100==0)_its.push_back({rand()%80,rand()%25,(char)(rand()%2?'W':'P')});char g[25][81];for(int y=0;y<25;y++)for(int x=0;x<80;x++)g[y][x]='~';for(auto&r:_raft)if(r.x>=0&&r.x<80&&r.y>=0&&r.y<25)g[r.y][r.x]='#';for(auto&i:_its)g[i.y][i.x]=i.t;g[_sy][_sx]='S';g[_py][_px]='@';system("cls");for(int y=0;y<25;y++){g[y][80]=0;std::cout<<g[y]<<"\n";}std::cout<<"wood:"<<_wood<<" hunger:"<<_hung<<" thirst:"<<_thi<<" raft:"<<_raft.size()<<"\n";Sleep(120);}return 0;}
